const SharePopup=(()=>{const s=document.createElement('style');s.textContent='.share-popup-overlay{position:fixed;top:0;left:0;width:100%;height:100%;background-color:rgba(0,0,0,.5);display:flex;justify-content:center;align-items:center;opacity:0;visibility:hidden;transition:all .3s ease-in-out;z-index:9999}.share-popup{background:#fff;width:90%;max-width:400px;border-radius:12px;padding:1.5rem;position:relative;transform:translateY(50px);transition:all .4s ease-in-out;box-shadow:0 4px 20px rgba(0,0,0,.1)}.share-popup.show{transform:translateY(0)}.share-popup-overlay.show{opacity:1;visibility:visible}.share-header{text-align:center;margin-bottom:1.5rem}.share-header h2{color:#333;font-size:1.5rem;margin-bottom:.5rem}.share-options{display:grid;grid-template-columns:repeat(4,1fr);gap:1rem;overflow:scroll;margin-bottom:1.5rem}.share-option{display:flex;flex-direction:column;align-items:center;gap:.5rem;cursor:pointer;padding:.5rem;border-radius:8px;transition:background-color .3s}.share-option:hover{background-color:#f3f4f6}.share-icon{width:40px;height:40px;border-radius:50%;display:flex;align-items:center;justify-content:center;color:#fff}.share-label{font-size:.75rem;color:#4b5563;text-align:center}.close-button{position:absolute;top:1rem;right:1rem;background:0;border:0;font-size:1rem;color:#6b7280;cursor:pointer;padding:.25rem;line-height:1}.close-button:hover{color:#000}.copy-url{display:flex;gap:.5rem;background-color:#f3f4f6;padding:.75rem;border-radius:8px;margin-top:1rem}.copy-url input{flex:1;border:0;background:0;outline:0;font-size:.875rem}.copy-button{background:#2563eb;color:#fff;border:0;padding:.5rem 1rem;border-radius:6px;cursor:pointer;font-size:.875rem}.copy-button:hover{background:#1d4ed8}.whatsapp .share-icon{background:#25D366}.facebook .share-icon{background:#1877F2}.telegram .share-icon{background:#0088cc}.twitter .share-icon{background:#1DA1F2}';const t='<div class="share-popup"><button class="close-button">&#10005;</button><div class="share-header"><h2>Share Post</h2></div><div class="share-options"><div class="share-option whatsapp"><div class="share-icon"><i class="fab fa-whatsapp"></i></div><span class="share-label">WhatsApp</span></div><div class="share-option facebook"><div class="share-icon"><i class="fab fa-facebook-f"></i></div><span class="share-label">Facebook</span></div><div class="share-option telegram"><div class="share-icon"><i class="fab fa-telegram-plane"></i></div><span class="share-label">Telegram</span></div><div class="share-option twitter"><div class="share-icon"><i class="fab fa-twitter"></i></div><span class="share-label">Twitter</span></div></div><div class="copy-url"><input type="text" readonly value="https://example.com/share-page"><button class="copy-button">Copy</button></div></div>',o=document.createElement('div');o.className='share-popup-overlay',o.innerHTML=t,document.head.appendChild(s),document.body.appendChild(o);const p={overlay:o,element:o.querySelector('.share-popup'),closeBtn:o.querySelector('.close-button'),copyBtn:o.querySelector('.copy-button'),urlInput:o.querySelector('.copy-url input'),shareData:{url:'<?php echo addslashes($canonicalURL); ?>',title:'<?php echo addslashes($postTitle); ?>',text:'Checkout this CareerJyoti Vacancy Updates!'},show(d={}){d.url&&(this.shareData.url=d.url),d.title&&(this.shareData.title=d.title),d.text&&(this.shareData.text=d.text),this.urlInput.value=this.shareData.url,this.overlay.classList.add('show'),this.element.classList.add('show')},hide(){this.overlay.classList.remove('show'),this.element.classList.remove('show')},async shareToWhatsApp(){const t=`${this.shareData.text}\n\n${this.shareData.title}\n\n${this.shareData.url}`;window.open(`whatsapp://send?text=${encodeURIComponent(t)}`,'_blank')},async shareToFacebook(){window.open(`https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(this.shareData.url)}`,'_blank')},async shareToTelegram(){const t=`${this.shareData.text}\n\n${this.shareData.title}\n\n${this.shareData.url}`;window.open(`tg://msg_url?url=${encodeURIComponent(this.shareData.url)}&text=${encodeURIComponent(t)}`,'_blank')},async shareToTwitter(){const t=`${this.shareData.text}\n\n${this.shareData.title}\n\n${this.shareData.url}`;window.open(`twitter://post?text=${encodeURIComponent(t)}`,'_blank')},init(){this.element.querySelector('.whatsapp').addEventListener('click',()=>this.shareToWhatsApp()),this.element.querySelector('.facebook').addEventListener('click',()=>this.shareToFacebook()),this.element.querySelector('.telegram').addEventListener('click',()=>this.shareToTelegram()),this.element.querySelector('.twitter').addEventListener('click',()=>this.shareToTwitter()),this.copyBtn.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(this.urlInput.value),this.copyBtn.textContent='Copied!',setTimeout(()=>{this.copyBtn.textContent='Copy'},2e3)}catch(e){console.error('Failed to copy:',e)}}),this.closeBtn.addEventListener('click',()=>this.hide()),this.overlay.addEventListener('click',e=>{e.target===this.overlay&&this.hide()})}};return p.init(),window.sharePopup=p,p})();